import{$ as e,Dt as t,Q as n,Y as r,ht as i,it as a,nt as o,o as s,rt as c,tt as l,yt as u}from"./chunks/framework.BDx6F-5s.js";var d=JSON.parse(`{"title":"SyncBoot: Digital Backend Framework Overview","description":"An enterprise backend platform supporting domain data operations and schema governance. Integrates Spring Boot 3, LangChain4j, and Model Context Protocol (MCP) to streamline system operations and API development.","frontmatter":{"title":"SyncBoot: Digital Backend Framework Overview","description":"An enterprise backend platform supporting domain data operations and schema governance. Integrates Spring Boot 3, LangChain4j, and Model Context Protocol (MCP) to streamline system operations and API development.","head":[["meta",{"name":"keywords","content":"SyncBoot, Java, Spring Boot 3, LangChain4j, AI Agent, Model Context Protocol, MCP, Low-Code, Enterprise Backend, 3-File SQL, RBAC, Multi-Tenant"}],["meta",{"property":"og:title","content":"SyncBoot: Digital Backend Framework Overview"}],["meta",{"property":"og:description","content":"An enterprise backend platform supporting domain data operations and schema governance."}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/syncboot/"}]]},"headers":[],"relativePath":"en/syncboot/index.md","filePath":"en/syncboot/index.md","lastUpdated":1787441667000}`),f={name:`en/syncboot/index.md`};function p(s,d,f,p,m,h){let g=u(`Mermaid`);return i(),l(`div`,null,[d[1]||=n(`h1`,{id:`syncboot-digital-backend-framework-overview`,tabindex:`-1`},[c(`SyncBoot: Digital Backend Framework Overview `),n(`a`,{class:`header-anchor`,href:`#syncboot-digital-backend-framework-overview`,"aria-label":`Permalink to “SyncBoot: Digital Backend Framework Overview”`},`​`)],-1),d[2]||=n(`p`,null,`SyncBoot is a Java-based enterprise backend platform designed to recognize business domain context and support database operations and API development.`,-1),d[3]||=n(`p`,null,`Built on Spring Boot 3, LangChain4j, and the Model Context Protocol (MCP) standard, SyncBoot provides capabilities for data CRUD operations, schema management, fullstack code scaffolding, and distributed log inspection.`,-1),d[4]||=n(`hr`,null,null,-1),d[5]||=n(`h2`,{id:`_4-core-functional-areas`,tabindex:`-1`},[c(`4 Core Functional Areas `),n(`a`,{class:`header-anchor`,href:`#_4-core-functional-areas`,"aria-label":`Permalink to “4 Core Functional Areas”`},`​`)],-1),(i(),e(r,null,{default:t(()=>[a(g,{id:`mermaid-13`,class:`mermaid`,graph:`graph%20LR%0A%20%20%20%20A%5BSyncBoot%204%20Core%20Areas%5D%20--%3E%20B%5B1.%20Domain%20CRUD%20Operations%5D%0A%20%20%20%20A%20--%3E%20C%5B2.%203-File%20Schema%20Governance%5D%0A%20%20%20%20A%20--%3E%20D%5B3.%20Fullstack%20Code%20Generator%5D%0A%20%20%20%20A%20--%3E%20E%5B4.%20Enterprise%20IAM%20%26%20Multi-Tenancy%5D%0A%0A%20%20%20%20B%20-.-%3E%20B1%5BNatural%20Language%20Queries%20%26%20Transactions%5D%0A%20%20%20%20C%20-.-%3E%20C1%5Binit%20%2F%20domain%20%2F%20sample%20Separation%20%26%20Pre-Approval%5D%0A%20%20%20%20D%20-.-%3E%20D1%5BSpring%20Boot%20%2B%20Vue3%20Scaffolding%5D%0A%20%20%20%20E%20-.-%3E%20E1%5BRow-Level%20Isolation%20%26%20Column%20Data%20Masking%5D%0A`})]),fallback:t(()=>[...d[0]||=[c(` Loading... `,-1)]]),_:1})),d[6]||=o(`<ol><li><p><strong>Domain CRUD Operations &amp; Query Execution</strong>:</p><ul><li>Supports domain data querying and manipulation through natural language queries and standardized MCP tools.</li><li>Executes database operations safely within authorized transaction boundaries.</li></ul></li><li><p><strong>Schema Design &amp; 3-File DDL Standard</strong>:</p><ul><li>Organizes database scripts into the 3-File SQL standard (<code>init.sql</code>, <code>&lt;domain&gt;.sql</code>, <code>sample.sql</code>).</li><li>Analyzes schema changes in advance and applies migrations following Human-in-the-Loop (HITL) engineer approval.</li></ul></li><li><p><strong>Low-Code Fullstack API &amp; UI Generator</strong>:</p><ul><li>Scaffolds Controllers, Services, Mappers, DTOs, and Ant Design Vue 3 frontend screens based on database entity metadata.</li></ul></li><li><p><strong>Multi-Tenancy &amp; RBAC Security</strong>:</p><ul><li>Supports tenant data isolation (both Shared DB and Dedicated DB modes), dynamic column-level data masking, and Row-Level Security (RLS) filtering.</li></ul></li></ol><hr><h2 id="_5-backend-worker-roles" tabindex="-1">5 Backend Worker Roles <a class="header-anchor" href="#_5-backend-worker-roles" aria-label="Permalink to “5 Backend Worker Roles”">​</a></h2><p>SyncBoot modularizes operational responsibilities across 5 specialized worker roles:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Role Name</th><th style="text-align:left;">Primary Responsibility</th><th style="text-align:left;">Execution Model</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Domain Operator</strong></td><td style="text-align:left;">Executes domain data CRUD and business transactions</td><td style="text-align:left;">Autonomous Execution</td></tr><tr><td style="text-align:left;"><strong>Schema Architect</strong></td><td style="text-align:left;">Designs 3-File DDLs, generates ERDs, and analyzes migration impact</td><td style="text-align:left;">Proposal + Developer Approval</td></tr><tr><td style="text-align:left;"><strong>Security IAM</strong></td><td style="text-align:left;">Enforces RBAC roles, row-level filters, and dynamic data masking</td><td style="text-align:left;">Continuous Policy Enforcement</td></tr><tr><td style="text-align:left;"><strong>MCP Dispatcher</strong></td><td style="text-align:left;">Exposes standard MCP Tools and Resources via HTTP SSE for A2A integration</td><td style="text-align:left;">Standard HTTP SSE Protocol</td></tr><tr><td style="text-align:left;"><strong>Batch Orchestrator</strong></td><td style="text-align:left;">Coordinates high-volume data pipelines and scheduled Quartz/Spring Batch jobs</td><td style="text-align:left;">Scheduler-driven Execution</td></tr></tbody></table><hr><h2 id="key-benefits" tabindex="-1">Key Benefits <a class="header-anchor" href="#key-benefits" aria-label="Permalink to “Key Benefits”">​</a></h2><ul><li><strong>Reduced Development Effort</strong>: Reduces repetitive tasks for standard CRUD APIs and administrative UI screens.</li><li><strong>Controlled Database Migrations</strong>: Pre-migration impact analysis and approval workflows reduce risks during schema updates.</li><li><strong>Faster Incident Diagnostics</strong>: Aggregates distributed server error logs to accelerate root-cause analysis.</li><li><strong>Standards Compliance</strong>: Complies with Spring Boot 3, LangChain4j, OpenAPI 3.0, and Model Context Protocol (MCP) specifications.</li></ul><hr><h2 id="documentation-navigation" tabindex="-1">Documentation Navigation <a class="header-anchor" href="#documentation-navigation" aria-label="Permalink to “Documentation Navigation”">​</a></h2><ul><li><a href="./quickstart">5-Minute QuickStart</a> - Launching local environment via Docker Compose</li><li><a href="./architecture">System Architecture &amp; Modules</a> - 4-layer architecture and worker structure</li><li><a href="./schema-studio">Intelligent Schema Studio</a> - 3-File DB standard and DDL approval process</li><li><a href="./lowcode-generator">Low-Code Fullstack Generator</a> - Scaffolding backend APIs and Vue 3 UI</li><li><a href="./enterprise-security">Multi-Tenancy &amp; RBAC Security</a> - Row-level security and data masking</li><li><a href="./batch-and-scheduler">Batch &amp; Job Scheduler</a> - Spring Batch and Quartz task management</li><li><a href="./mcp-and-ai">LangChain4j &amp; MCP Integration</a> - Model Context Protocol specifications</li><li><a href="./production-guide">Production Deployment &amp; Metrics</a> - Container deployment and performance metrics</li><li><a href="./h2">H2 Embedded Database Setup</a> - Local development and unit testing setup</li></ul>`,11)])}var m=s(f,[[`render`,p]]);export{d as __pageData,m as default};